mapper.select:
select r.*, d.id as dept_id FROM data_role r join depts_data_roles dr on r.id = dr.data_role_id join dept d on dr.dept_id = d.id and d.status = 1 where r.`status`= #{status}
and d.id = #{deptId}
and (r.name like concat('%',#{filterVal},'%') or r.created_user like concat('%',#{filterVal},'%')
or r.id = #{orId}
)
order by r.created_time desc
